    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize creating "fragmented" space (residual 1-9)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Prioritize Best-Fit behavior by rewarding smaller post-residuals,
    // but dampen this as we approach the end of the stream (where packing density matters more)
    score -= (1.0 - progress) * (bin_capacity - post_residual) as f64 * 0.1;

    // 3. Lookahead logic: If the next item fits into the current post_residual, 
    // heavily reward this bin to create "pairs" (Best Fit for next item)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
    }

    // 4. Global state adjustment: Penalize opening new bins when many open bins have high residuals
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 50.0;
        }
        // Early in the stream, be more conservative about opening new bins
        score += (1.0 - progress) * 20.0;
    }

    // 5. If this is the only bin that fits the item, make it very attractive to avoid wasted space
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Non-linear penalty for creating very empty bins early on
    if bin_residual == bin_capacity && progress < 0.8 {
        score += (item_size as f64 / bin_capacity as f64) * 15.0;
    }

    score
