    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Favor bins that leave the smallest residual space.
    // This is the baseline score.

    // 2. Lookahead Penalty/Reward:
    // If the next item fits into the post_residual, drastically lower the score to prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 150.0;
        // Further refine by penalizing if we leave a tiny, unusable sliver after fitting the next item.
        if (post_residual - next_item_size) < 10 {
            score += 20.0;
        }
    }

    // 3. Mean Residual Balancing:
    // Penalize bins that deviate too far from the current average density to keep bins uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless it's the only option or the current fitting bins are extremely poor.
    if bin_residual == bin_capacity {
        score += 65.0; 
        // If we are late in the stream, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 40.0;
    }

    // 5. Scarcity Handling:
    // If this is the last fitting bin available, reduce penalty to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Dead Space Avoidance:
    // Heavily penalize specific "bad" residuals (e.g., 1-9) that are unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    score
}

