pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_res;

    // Penalty for creating 'dead space' (small residuals that are hard to fill later)
    // We penalize residuals in the range (0, 15) exponentially.
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post_res).powi(2) * 2.5;
    }

    // Lookahead logic: If a future item is large, avoid small post_residuals in the current bin
    // that would prevent placing the next item in this bin.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Progression coupling: As the stream nears the end, become more conservative about opening
    // new bins. We penalize the 'new bin' case (bin_residual == bin_capacity) increasingly 
    // as we reach the end of the stream.
    if bin_residual == bin_capacity {
        score += 20.0 + (progress * 50.0);
    }

    // Contextual adjustment: If only one bin fits the item, it is a critical placement.
    // We reduce the score to ensure we don't accidentally open a new bin instead.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Balance the open bin count: avoid excessive fragmentation early on.
    score += (open_bins_count as f64 * 0.5) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: penalize large post_residuals (dead space)
    // We favor bins that become very tight (Best-Fit principle)
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead optimization: If the next item fits into the current post_residual,
    // we strongly reward this bin to avoid fragmentation.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 25.0;
    }

    // 3. Fragmentation penalty: If this is the only bin that fits the current item,
    // we make it highly attractive to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // 4. Harmonic balancing: Penalize creating bins that are "awkward" (e.g., residual 1-9)
    // because they are unlikely to fit future items (min size 10).
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // 5. Global density management: If we are late in the stream, favor filling 
    // existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // Penalize opening new bins, scaling penalty by progress
        score += 200.0 * (1.0 + progress);
    }

    // 6. Mean-Residual alignment: If this bin's residual after placement is 
    // significantly higher than the average, it's a poor candidate.
    if (post_residual as f64) > mean_residual {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // 2. Harmonic/Modulo constraint: If post_residual is a multiple of 10 or 20, 
    // it likely leaves space for common item sizes (10, 20, 25, 40, 50).
    let harmonic_penalty = if post_residual % 10 == 0 { -5.0 } else { 2.0 };
    score += harmonic_penalty;

    // 3. Lookahead integration: Try to minimize the gap left for the next item.
    // If the next item fits perfectly into the post_residual, reward this bin heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            // Reward configurations that leave exactly 0 or small gaps for the next item
            score -= (100.0 / (gap + 1) as f64);
        } else {
            // Penalize if the next item won't fit, especially if this is the only bin that could fit current
            score += 10.0;
        }
    }

    // 4. Thresholding: Avoid opening new bins unless current open bins are very full
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual is already quite low (bins are full)
        if mean_residual > 20.0 && open_bins_count > 0 {
            score += 50.0; 
        } else {
            score += 15.0;
        }
    }

    // 5. Fitting constraint: If this is the only bin that fits the current item, 
    // prioritize it to avoid wasting a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 6. Progression scaling: As we approach the end of the stream, be more conservative
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize Best Fit (minimize post_residual)
    let mut score = post;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We penalize post-residuals that are smaller than the smallest possible item (10).
    if post > 0.0 && post < 10.0 {
        score += 20.0 * (1.0 - post / 10.0);
    }

    // Lookahead logic: If a second item is known, prioritize bins that can accommodate it.
    // If next_item_size > post_residual, we create a constraint penalty.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding: Near the end of the stream, prioritize closing bins
    // to avoid leaving too many partially filled bins.
    if progress > 0.8 {
        score -= (bin_capacity as f64 - post) * 0.5;
    }

    // Heuristic for new bin creation:
    // If this is an empty bin (bin_residual == bin_capacity), assess if it's worth opening.
    if bin_residual == bin_capacity {
        // Base cost to open a new bin is high.
        // We reduce this cost if we have many open bins already or if the item is large.
        let open_penalty = 45.0 - (open_bins_count as f64 * 0.5) - (item_size as f64 * 0.2);
        score = open_penalty;
    } else {
        // Favor bins that are already well-utilized (lower mean_residual)
        // to encourage packing density.
        score += (mean_residual - post) * 0.2;
    }

    // Final scaling: favor bins that are the "last chance" to fit the item
    // to prevent unnecessary bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize large post_residuals (dead space).
    // We favor tight fits that leave very little space.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead matching: If post_residual can perfectly or nearly accommodate the next item,
    // we reward this placement to prevent future bin opening.
    if next_item_size > 0 && post_residual >= next_item_size {
        // High reward for a "perfect" match with the lookahead item.
        let waste_after_next = (post_residual - next_item_size) as f64;
        score -= (100.0 - waste_after_next).powi(2) * 0.5;
    }

    // 3. Avoid opening new bins unless necessary:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless fitting_bins_count is 0 (i.e., no other choice).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 500.0;
        } else {
            // If we must open a new bin, penalize based on how much the item
            // wastes the new bin's potential.
            score += (bin_capacity - item_size) as f64 * 2.0;
        }
    }

    // 4. Global balance: If we have many open bins, prioritize closing them by
    // filling them to near-zero residuals.
    if open_bins_count > 5 {
        score += (post_residual as f64) * 0.5;
    }

    // 5. Progression adjustment: As the stream nears completion, become more
    // aggressive about consolidating space.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64);

    score
}
